        if 2 not in factors:
            factors.append(2)
        n //= 2
    # n must be odd at this point, so a skip of 2 is possible
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            if i not in factors:
                factors.append(i)
            n //= i
    # Condition if n is a prime number greater than 2
